<script lang="ts">
 import {onMount,tick} from 'svelte';
 import {base} from '$app/paths';
 import TableInvite from '$lib/components/play/TableInvite.svelte';
 import {parseTableCode} from '$lib/backend/codes';
 import GameTable from '$lib/components/play/GameTable.svelte';
 import {firebase} from '$lib/backend/firebase';
 import {resolveTableCode,shareTableCode,createGame,joinGame,canResumeGame,watchGame,readGame,append,liveChannel,type LiveChannel} from '$lib/backend/repository';
 import {botCommand} from '$lib/engine/bot';
 import {applyEvent,commandEvent,replay,type State,type Command,type GameEvent,type Group} from '$lib/engine/engine';
 import type {LiveDraft} from '$lib/backend/live';
 let uid=$state(''),gameState=$state<State|null>(null),tableId=$state(''),shareCode=$state(''),name=$state(''),code=$state(''),invited=$state(false),error=$state(''),liveStatus=$state(''),busy=$state(false),connecting=$state(true),practice=$state(false),liveDraft=$state<LiveDraft|null>(null),origin=$state(''),menuOpen=$state(false),replayMode=$state(false),cursor=$state(0),replayCount=$state(0),timeline=$state<GameEvent[]>([]),animationBusy=$state(false);
 let latestDraft:{groups:Group[];turn:number;purgatory:string|null}|null=null;let heartbeat:ReturnType<typeof setInterval>|undefined;let expiry:ReturnType<typeof setInterval>|undefined;let off:(()=>void)|undefined,channel:LiveChannel|undefined,botTimer:ReturnType<typeof setTimeout>|undefined,disposed=false,events:GameEvent[]=[];
 function receive(next:State,transcript?:GameEvent[]){if(disposed||replayMode)return;if(transcript&&(!gameState||next.revision>=gameState.revision))timeline=transcript;else if(practice)timeline=[...events];if(gameState&&gameState.revision>=next.revision)return;gameState=next;if(!practice)void channel?.authorize(next).catch(e=>liveStatus=e.message);scheduleBot();}
 async function connect(id:string){lastAutoKeep='';off?.();channel?.close();gameState=null;id=await resolveTableCode(id);shareCode=await shareTableCode(id);tableId=id;history.replaceState(null,'',`${base}/play?table=${shareCode}`);localStorage.setItem('hp-table',id);off=await watchGame(id,receive,e=>error=e.message);channel=await liveChannel(id,d=>{liveDraft=d;},e=>{liveStatus=`Live table: ${e.message}`;},()=>liveStatus='');const s=await readGame(id);receive(s);await channel.authorize(s);}
 async function run(work:()=>Promise<void>){if(busy)return;busy=true;error='';try{await work();}catch(e){error=e instanceof Error?e.message:String(e);}finally{busy=false;scheduleBot();}}
 async function send(c:Command,actor=uid){if(!gameState)return;let next:State;if(practice){const e=commandEvent(gameState,actor,c,crypto.randomUUID());next=applyEvent(gameState,e);events.push(e);localStorage.setItem('hp-practice',JSON.stringify(events));receive(next);}else{next=await append(tableId,gameState,actor,c);receive(next);}if(c.type==='draw'&&next.phase==='inspect'&&next.inspection?.player===actor&&next.inspection.tiles.length===1){await tick();await send({type:'keep',tile:next.inspection.tiles[0],turn:next.turnNumber},actor);}}
 let lastAutoKeep='';
 $effect(()=>{const s=gameState;if(!s||busy||connecting||replayMode||s.phase!=='inspect'||s.inspection?.player!==uid||s.inspection.tiles.length!==1)return;const key=`${tableId}/${s.turnNumber}/${s.inspection.tiles[0]}`;if(lastAutoKeep===key)return;lastAutoKeep=key;void run(()=>send({type:'keep',tile:s.inspection!.tiles[0],turn:s.turnNumber}));});
 async function human(c:Command){if(replayMode)return;await run(()=>send(c));}
 function scheduleBot(){clearTimeout(botTimer);if(replayMode||!gameState||busy||animationBusy||gameState.owner!==uid||disposed)return;for(const p of gameState.players.filter(p=>p.bot)){const c=botCommand(gameState,p);if(c){botTimer=setTimeout(()=>void run(()=>send(c,p.id)),450);return;}}}
 function animationChanged(active:boolean){animationBusy=active;if(active)clearTimeout(botTimer);else scheduleBot();}
 function publish(groups:Group[],dragging:boolean,purgatory:string|null){if(gameState)latestDraft={groups,purgatory,turn:gameState.turnNumber};if(!practice&&!replayMode&&gameState&&gameState.players[gameState.turn]?.id===uid)channel?.publish({version:1,revision:gameState.revision,turn:gameState.turnNumber,actor:uid,groups,purgatory,dragging});}
 function startPractice(){off?.();channel?.close();practice=true;tableId='practice';uid='practice-player';events=[];gameState=null;const e=commandEvent(null,uid,{type:'create',name:name.trim()||'You',seed:crypto.randomUUID()},crypto.randomUUID());events.push(e);receive(applyEvent(null,e));void run(async()=>{await send({type:'bot',id:'practice-bot-1',name:'Cassiel'});await send({type:'bot',id:'practice-bot-2',name:'Ariel'});await send({type:'start'});});history.replaceState(null,'',`${base}/play?practice=1`);}
 const inviteUrl=$derived(`${origin}${base}/play?table=${shareCode}`);
 function leaveTable(){off?.();off=undefined;channel?.close();channel=undefined;clearTimeout(botTimer);latestDraft=null;liveDraft=null;gameState=null;tableId='';shareCode='';events=[];timeline=[];practice=false;replayMode=false;animationBusy=false;menuOpen=false;invited=false;code='';error='';liveStatus='';localStorage.removeItem('hp-table');history.replaceState(null,'',`${base}/play`);}
 async function joinTable(){const id=parseTableCode(code);practice=false;replayMode=false;uid=(await firebase()).uid;await joinGame(id,name);await connect(id);}
 async function makeTable(){practice=false;replayMode=false;uid=(await firebase()).uid;const id=await createGame(name);await connect(id);}
 function openDialog(node:HTMLDialogElement){node.showModal();}
 async function exportReplay(){const {db}=practice||replayMode?{db:null}:await firebase();const {getDocs,collection,query,orderBy}=await import('firebase/firestore');const log=practice||replayMode?events:(await getDocs(query(collection(db!,'games',tableId,'events'),orderBy('sequence')))).docs.map(d=>{const {createdAt,...e}=d.data();return e;});const url=URL.createObjectURL(new Blob([JSON.stringify({game:'higher-powers',version:1,events:log},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`higher-powers-${tableId}.json`;a.click();URL.revokeObjectURL(url);}
 function stepReplay(value:number){cursor=value;timeline=events.slice(0,value);gameState=replay(timeline);if(!gameState.players.some(p=>p.id===uid))uid=gameState.owner;}
 async function openReplay(file:File){if(file.size>25000000)throw new Error('That replay is too large.');const data=JSON.parse(await file.text());if(data.game!=='higher-powers'||data.version!==1||!Array.isArray(data.events))throw new Error('Choose a Higher Powers replay file.');const restored=replay(data.events);off?.();channel?.close();clearTimeout(botTimer);replayMode=true;practice=false;events=data.events;timeline=[...events];replayCount=events.length;cursor=events.length;uid=restored.owner;gameState=restored;tableId='replay';}
 onMount(()=>{heartbeat=setInterval(()=>{if(gameState&&latestDraft?.turn===gameState.turnNumber&&gameState.phase==='play'&&gameState.players[gameState.turn].id===uid)publish(latestDraft.groups,false,latestDraft.purgatory);},10000);expiry=setInterval(()=>{if(liveDraft&&Date.now()-liveDraft.sentAt>45000)liveDraft=null;},2000);origin=location.origin;name=localStorage.getItem('hp-name')??'';const params=new URL(location.href).searchParams,rawId=params.get('table');let id:string|null=null;if(rawId){try{id=parseTableCode(rawId);}catch(e){error=(e as Error).message;}}if(params.get('practice')==='1'&&localStorage.getItem('hp-practice')){try{events=JSON.parse(localStorage.getItem('hp-practice')!);const restored=replay(events);practice=true;uid=restored.owner;tableId='practice';receive(restored);}catch{error='The saved practice game could not be replayed.';}}code=id??rawId??'';invited=!!rawId;if(!id)connecting=false;void(async()=>{if(practice||replayMode)return;try{const client=await firebase();if(!practice&&!replayMode)uid=client.uid;if(id&&await canResumeGame(id))await connect(id);}catch(e){if(!practice&&!replayMode)error=e instanceof Error?e.message:String(e);}finally{connecting=false;}})();return()=>{disposed=true;off?.();channel?.close();clearTimeout(botTimer);clearInterval(expiry);clearInterval(heartbeat);};});
</script>
<svelte:head><title>Play Higher Powers</title><meta name="description" content="Play Higher Powers together at a live shared table."/></svelte:head>
{#snippet invitation()}<TableInvite code={shareCode} url={inviteUrl}/>{/snippet}
{#snippet tableMenu()}<div class="table-access">{#if !practice&&!replayMode}<button class="visible-table-code" title="Invite friends" aria-label={`Table code ${shareCode}. Invite friends`} onclick={()=>menuOpen=true}>{shareCode}</button>{/if}<button class="table-menu" aria-label="Table menu" title="Table menu" onclick={()=>menuOpen=true}><svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.5"><path d="m16 4 3 7 8 5-8 4-3 8-4-8-8-4 8-5Z"/><circle cx="16" cy="16" r="3"/></svg></button></div>{/snippet}
{#if menuOpen}<dialog class="table-dialog" use:openDialog onclose={()=>menuOpen=false} oncancel={()=>menuOpen=false} aria-label="Table menu"><button class="close-menu" aria-label="Close table menu" onclick={()=>menuOpen=false}>×</button>{#if !practice&&!replayMode}{@render invitation()}{:else}<h2>{practice?'Practice table':'Replay'}</h2>{/if}<nav><button onclick={()=>void run(exportReplay)}>Save replay</button><a href={`${base}/rules.html`} target="_blank" rel="noreferrer">Rulebook ↗</a><button onclick={leaveTable}>Leave table</button></nav></dialog>{/if}
<main id="main" class="play-page" class:at-table={!!gameState}>
 {#if !gameState&&!connecting}<div class="play-header"><a href={`${base}/`}>Higher <em>Powers</em></a><a href={`${base}/rules.html`} target="_blank" rel="noreferrer">Rules ↗</a></div>{/if}
 {#if error}<div class="error" role="alert">{error}<button onclick={()=>error=''} aria-label="Dismiss error">×</button></div>{/if}
 {#if liveStatus}<p class="live-warning" role="status">{liveStatus} <button onclick={()=>void run(()=>connect(tableId))}>Reconnect</button></p>{/if}
 {#if connecting}<p>Opening the gates…</p>
 {:else if !gameState}<section class="welcome"><p class="eyebrow">THE GRAND ORDER · 2–5 PLAYERS</p><h1>{invited?'Join your friends':'Heaven is yours to rearrange.'}</h1><p>{invited?'Enter your name, then join the table below.':'Bring friends to a live table, or try your Angel’s gift with two computer players.'}</p><label>Your name<input maxlength="40" bind:value={name} placeholder="An ambitious angel" oninput={()=>localStorage.setItem('hp-name',name)}/></label>{#if !invited}<div class="lobby-actions"><button class="primary" disabled={busy||!name.trim()} onclick={()=>void run(makeTable)}>Create a table</button><button disabled={busy} onclick={startPractice}>Practice with computers</button></div>{/if}<div class="join"><label>Table code or invite link<input bind:value={code} placeholder="ABCDE or an invite link" autocapitalize="characters" autocomplete="off" spellcheck="false"/></label><button disabled={busy||!code||!name.trim()} onclick={()=>void run(joinTable)}>Join table</button></div><label class="replay-upload">Open a saved replay<input type="file" accept=".json,application/json" onchange={e=>{const file=e.currentTarget.files?.[0];if(file)void run(()=>openReplay(file));}}/></label><a href={`${base}/gallery?collection=digital`}>Explore the components</a><a href={`${base}/tabletop`}>Play around one shared touchscreen</a></section>
 {:else if gameState.players.some(p=>p.id===uid)}{#if replayMode}<section class="replay-controls"><button disabled={cursor<=1} onclick={()=>stepReplay(cursor-1)}>←</button><label>Event {cursor} of {replayCount}<input type="range" min="1" max={replayCount} value={cursor} oninput={e=>stepReplay(Number(e.currentTarget.value))}/></label><button disabled={cursor>=replayCount} onclick={()=>stepReplay(cursor+1)}>→</button><select aria-label="Replay viewpoint" bind:value={uid}>{#each gameState.players as p}<option value={p.id}>{p.name}</option>{/each}</select></section>{/if}<GameTable invitation={!practice&&!replayMode?invitation:undefined} utilities={tableMenu} state={gameState} {uid} busy={busy||replayMode} events={timeline} animateMoves={!replayMode} onAnimating={animationChanged} send={human} {liveDraft} {publish} {tableId}/>{/if}
</main>
<style>
 .at-table{position:fixed;inset:0;padding:0;max-width:none;margin:0}.table-access{display:flex;align-items:center;gap:7px;flex-wrap:wrap}.table-menu{display:grid;place-items:center;width:29px;height:29px;padding:0;min-height:0;border:0;background:none;color:#d8c18a;cursor:pointer}.table-menu svg{width:25px;height:25px}.visible-table-code{padding:5px 7px;min-height:0;background:#f3e5c0;color:#5e4828;border:1px solid #bda16a;border-radius:4px;font:700 13px/1.2 monospace;letter-spacing:.07em}.table-dialog{position:fixed;inset:0;margin:auto;max-width:min(500px,calc(100vw - 24px));max-height:calc(100dvh - 24px);overflow:auto;width:480px;padding:28px 18px 18px;border:1px solid #c3a76a;border-radius:12px;background:#f4e8c9;color:#5d492a;box-sizing:border-box;box-shadow:0 15px 60px #061e1966}.table-dialog::backdrop{background:#071f19bb;backdrop-filter:blur(4px)}.close-menu{position:absolute;right:8px;top:4px;background:none;border:0;min-height:0;padding:0 5px;color:#5d492a;font:26px/1 sans-serif}.table-dialog nav{display:flex;flex-wrap:wrap;gap:10px;margin-top:16px}.table-dialog nav button,.table-dialog nav a{display:block;padding:9px 12px;margin:0;border:1px solid #bda16a;border-radius:5px;background:#fff8e6;color:#5d492a;font:14px/1.3 sans-serif;text-decoration:none}.table-dialog h2{margin:0}
 .at-table>.error,.at-table>.live-warning{position:fixed;top:30%;left:50%;transform:translateX(-50%);max-width:75vw;z-index:900;background:#fae8cf;box-shadow:0 8px 25px #071e1888}.at-table>.replay-controls{position:fixed;left:10%;right:10%;top:50%;z-index:900}.replay-upload{font-size:14px}.replay-controls{display:flex;gap:12px;align-items:center;padding:12px;background:#ede2c7;border-radius:8px;margin:12px 0}.replay-controls label{flex:1;display:grid;font-size:13px}.replay-controls input{width:100%}:global(body:has(.play-page) .site-header),:global(body:has(.play-page) .site-footer){display:none}.play-page{padding:14px clamp(10px,2vw,30px) 30px;max-width:1660px;margin:auto}.play-header{display:flex;justify-content:space-between;gap:12px;align-items:center}.play-header>a{font:600 31px 'Cormorant Garamond';text-decoration:none}.welcome{max-width:740px;margin:10vh auto;padding:36px;background:#fcf6e8;border:1px solid #c6b07a;border-radius:14px}.welcome h1{font-size:clamp(36px,5vw,56px);line-height:1.05}.welcome p{max-width:55ch}.welcome label{display:grid;gap:6px;margin:20px 0 10px}.welcome input{font:inherit;padding:12px;border:1px solid #bca879;border-radius:5px;background:#fffdf7;max-width:100%}.lobby-actions{display:flex;gap:12px;flex-wrap:wrap}.join{margin:28px 0;display:flex;align-items:end;gap:10px}.join label{flex:1;margin:0}.join button{margin-bottom:0}.error{display:flex;justify-content:space-between;align-items:center;gap:14px;padding:12px 18px;background:#f9ddd7;border:1px solid #a85d4b;border-radius:6px;margin:12px 0}.error button{padding:0;border:0;background:none;min-height:0;font-size:20px}.live-warning{font-size:13px;color:#765b2c}button.primary{background:#56603d;color:#fff9e9}button:disabled{opacity:.5}@media(max-width:600px){.play-header{align-items:start}.play-header>a{font-size:24px;min-width:120px}.welcome{padding:22px;margin:5vh auto}.join{flex-direction:column;align-items:stretch}}
</style>
